  Lemma call_body : forall own k st ms {B} (K : Z -> @M PState B) (Q : B -> PState -> machine_state -> Prop),
    1 <= k <= 4 -> match own with None => plen = 0 | Some _ => True end -> RUNST own 0x13128 k st ms ->
    (forall rc' st' ms', RUNST own (if k =? 1 then 0x13160 else 0x13128) (k - 1) st' ms' -> rc' = 0 -> implM usegs (K rc') st' Q ms') ->
    implM usegs (rc' <- Prog.fuzz_one payload ;; io_emit Prog.io rc' ;;; K rc') st Q ms.
